}

// What each member of the group is owed (positive) or owes (negative), in the group's member order.
export function balances(state, group) {
  return Object.fromEntries([...balanceCents(state, group)].map(([name, cents]) => [name, toAmount(cents)]))
}

// The member furthest on one side: sign 1 is owed the most, sign -1 owes the most. Ties go to the member who
// comes first in the map; null when nobody is on that side.
function furthest(cents, sign) {
  let best = null
  for (const [name, value] of cents) {
    if (value * sign > 0 && (best === null || value * sign > cents.get(best) * sign)) best = name
  }
  return best
}

// Payments that would bring every balance to 0, as [{from, to, amount}]: the member who owes the most pays the
// member who is owed the most whichever is smaller of the two, until nobody owes anything.
export function settleUp(state, group) {
  const left = balanceCents(state, group)
  const payments = []
  let from = furthest(left, -1)
  let to = furthest(left, 1)
  while (from && to) {
    const cents = Math.min(-left.get(from), left.get(to))
    payments.push({ from, to, amount: toAmount(cents) })
    left.set(from, left.get(from) + cents)
    left.set(to, left.get(to) - cents)
    from = furthest(left, -1)
    to = furthest(left, 1)
  }
  return payments
}
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp } from '../server.mjs'

// A data file in a fresh temp folder; cleanup() deletes the folder.
export function tempDataFile() {
  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
export async function startApp(dataFile) {
  const server = createApp(dataFile)
  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', resolve)
  })
  const base = `http://127.0.0.1:${server.address().port}`
  return {
    call: (method, path, body) => request(base + path, method, body),
    stop: () => new Promise(resolve => server.close(resolve)),
  }
}

// Runs fn with a running app on its own data file, then stops it and deletes the file.
export async function withApp(fn) {
  const data = tempDataFile()
  const app = await startApp(data.file)
  try {
    await fn(app.call)
  } finally {
    await app.stop()
    data.cleanup()
  }
}

async function request(url, method, body) {
  const init = { method }
  if (body !== undefined) {
    init.headers = { 'content-type': 'application/json' }
    init.body = typeof body === 'string' ? body : JSON.stringify(body)
  }
  const res = await fetch(url, init)
  const text = await res.text()
  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
}
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { balances, expenseView, paymentView, settleUp, splitEvenly } from '../lib/ledger.mjs'

const group = { id: 'trip', name: 'Trip', members: ['Ann', 'Ben', 'Cara'] }

test('splitEvenly gives everyone the same part, in the order given', () => {
  assert.deepEqual(splitEvenly(900, ['Cara', 'Ann', 'Ben']), [['Cara', 300], ['Ann', 300], ['Ben', 300]])
  assert.deepEqual(splitEvenly(1250, ['Ann']), [['Ann', 1250]])
})

test('expenseView shows amounts as numbers with each share', () => {
  const expense = { id: 4, group: 'trip', description: 'Fuel', payer: 'Ben', amount: 1250, split: ['Ann', 'Ben'] }
  assert.deepEqual(expenseView(expense), {
    id: 4, description: 'Fuel', payer: 'Ben', amount: 12.5, split: ['Ann', 'Ben'], shares: { Ann: 6.25, Ben: 6.25 },
  })
})

test('paymentView shows the amount as a number', () => {
  assert.deepEqual(paymentView({ id: 2, group: 'trip', from: 'Ben', to: 'Ann', amount: 725 }), { id: 2, from: 'Ben', to: 'Ann', amount: 7.25 })
})

test('balances starts every member at 0', () => {
  const state = { groups: [group], expenses: [], payments: [] }
  assert.deepEqual(balances(state, group), { Ann: 0, Ben: 0, Cara: 0 })
})

test('balances: the payer is owed the others\' shares, and payments move money back', () => {
  const state = {
    groups: [group],
    expenses: [
      { id: 1, group: 'trip', description: 'Hotel', payer: 'Ann', amount: 9000, split: ['Ann', 'Ben', 'Cara'] },
      { id: 2, group: 'trip', description: 'Taxi', payer: 'Ben', amount: 2000, split: ['Ben', 'Cara'] },
      { id: 3, group: 'other', description: 'Elsewhere', payer: 'Ann', amount: 5000, split: ['Ann', 'Ben'] },
    ],
    payments: [{ id: 1, group: 'trip', from: 'Cara', to: 'Ann', amount: 3000 }],
  }
  assert.deepEqual(balances(state, group), { Ann: 30, Ben: -20, Cara: -10 })
})

test('settleUp is empty when everyone is square', () => {
  const state = { groups: [group], expenses: [], payments: [] }
  assert.deepEqual(settleUp(state, group), [])
})

test('settleUp: whoever owes the most pays whoever is owed the most, until all are square', () => {
  const four = { ...group, members: ['Ann', 'Ben', 'Cara', 'Dev'] }
  const pay = (id, from, to, amount) => ({ id, group: 'trip', from, to, amount })
  // Balances: Ann 50, Ben 30, Cara -60, Dev -20.
  const state = { groups: [four], expenses: [], payments: [pay(1, 'Ann', 'Cara', 5000), pay(2, 'Ben', 'Dev', 2000), pay(3, 'Ben', 'Cara', 1000)] }
  assert.deepEqual(settleUp(state, four), [
    { from: 'Cara', to: 'Ann', amount: 50 },
    { from: 'Dev', to: 'Ben', amount: 20 },
    { from: 'Cara', to: 'Ben', amount: 10 },
  ])
})
